effect.shader:
vec4 tex(vec2 p){ return texture2DCv(inputImg.texture, p); }
void main(){
vec2 uv = acScreenNorm;
vec4 src = tex(uv);
float aspect = acScreenSize.x / max(acScreenSize.y, 1.0);
vec2 q = uv - vec2(cx, cy);
q.x *= aspect;
float r = length(q);
float ph = r * freq * 6.28318530718 - acTime * speed * 6.28318530718;
float ring = pow(0.5 + 0.5 * sin(ph), sharp);
float k = clamp(ring * strength * waveColor.a, 0.0, 1.0) * mixAmt;
gl_FragColor = vec4(mix(src.rgb, waveColor.rgb, k), src.a);
}
